# Read build_toc_div and nest_toc_tokens
with open('markdown/extensions/toc.py') as f:
    lines = f.readlines()

# Find nest_toc_tokens (lines 172-?)
start = None
for i, line in enumerate(lines):
    if 'def nest_toc_tokens' in line:
        start = i
        break

end = len(lines)
for i in range(start+1, len(lines)):
    if lines[i].strip() and not lines[i].startswith(' ') and not lines[i].startswith('\t'):
        end = i
        break

print("nest_toc_tokens:")
print(''.join(lines[start:end]))
